const $=id=>document.getElementById(id);
const palette={Green:'#71856b',Blue:'#9bb8cb',Brown:'#9c8064',Cream:'#e5ddc4',White:'#fff',Red:'#b97565',Navy:'#41546c',Yellow:'#dbcb86',Black:'#454643',Orange:'#c89766',Purple:'#9a89ac',Other:'#c7c7be'};
const types=['Soccer','Basketball','Baseball','Football','Hockey','Rugby','Other'];
let records=[],selectedTypes=new Set(),selectedColors=new Set(),editingId=null,draftPhoto='',view='grid',saving=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function photoMarkup(r,extra=''){const sample=!r.photo&&r.sample&&Number.isInteger(r.tile);return `<div class="jersey-image ${sample?'sample-photo':''} ${extra}" ${sample?`style="--x:${r.tile%3*50}%;--y:${Math.floor(r.tile/3)*100}%" role="img" aria-label="Illustrative photo of ${esc(r.name)}"`:''}>${r.photo?`<img src="${esc(r.photo)}" alt="${esc(r.name)}">`:sample?'':`<span class="image-placeholder">Your next story<small>NO PHOTO YET</small></span>`}${extra?'':`<span class="year-badge">${esc(r.year)}</span>`}</div>`}
function renderFilters(){
 $('typeFilters').innerHTML=types.map(t=>`<label class="type-filter"><input type="checkbox" value="${t}" ${selectedTypes.has(t)?'checked':''}><span>${t}</span><span class="count">${records.filter(r=>r.type===t).length}</span></label>`).join('');
 $('typeFilters').querySelectorAll('input').forEach(input=>input.onchange=()=>{input.checked?selectedTypes.add(input.value):selectedTypes.delete(input.value);render()});
 $('colorFilters').innerHTML=Object.entries(palette).map(([color,hex])=>`<button type="button" class="swatch ${selectedColors.has(color)?'selected':''}" style="--swatch:${hex}" title="${color}" aria-label="Filter ${color} jerseys" aria-pressed="${selectedColors.has(color)}" data-color="${color}"></button>`).join('');
 $('colorFilters').querySelectorAll('button').forEach(button=>button.onclick=()=>{const c=button.dataset.color;selectedColors.has(c)?selectedColors.delete(c):selectedColors.add(c);renderFilters();render()});
}
function filtered(){const q=$('search').value.toLowerCase().trim(),year=new Date().getFullYear();let found=records.filter(r=>{const age=year-r.year;return (!q||[r.name,r.team,r.type,r.color,r.year,r.number,r.notes,r.condition,r.size].join(' ').toLowerCase().includes(q))&&(!selectedTypes.size||selectedTypes.has(r.type))&&(!selectedColors.size||selectedColors.has(r.color))&&($('size').value==='all'||r.size===$('size').value)&&($('era').value==='all'||($('era').value==='vintage'&&age>=20)||($('era').value==='retro'&&age>=10&&age<20)||($('era').value==='modern'&&age<10))});const s=$('sort').value;if(s==='oldest')found.sort((a,b)=>a.year-b.year);if(s==='newest')found.sort((a,b)=>b.year-a.year);if(s==='name')found.sort((a,b)=>a.name.localeCompare(b.name));return found;}
function render(){const found=filtered();$('total').textContent=String(records.length).padStart(2,'0');$('resultCount').textContent=`${found.length} of ${records.length} jerseys`;$('demo').hidden=!records.some(r=>r.sample);$('cards').className=`cards ${view==='list'?'list':''}`;
 $('cards').innerHTML=found.map(r=>`<button class="card" data-id="${esc(r.id)}" aria-label="View ${esc(r.name)}">${photoMarkup(r)}<div class="card-body"><span class="card-type">${esc(r.type)} · ${esc(r.year)}</span><h3>${esc(r.name)}</h3><p class="card-team">${esc(r.team||'Independent collection')}${r.number?' · '+esc(r.number):''}</p><div class="card-meta"><span class="color-dot" style="--swatch:${palette[r.color]||palette.Other}"></span><span>${esc(r.color)}</span><span>·</span><span>Size ${esc(r.size)}</span><span class="condition">${esc(r.condition)}</span></div></div></button>`).join('');
 $('cards').querySelectorAll('.card').forEach(card=>card.onclick=()=>showDetail(card.dataset.id));$('empty').hidden=found.length>0;$('emptyText').textContent=records.length?'Try a different search or reset your filters.':'Add your first jersey and give it a place in your archive.';$('emptyAction').textContent=records.length?'Reset filters':'Add a jersey';
}
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,4200)}
async function persist(next){if(saving)throw Error('A save is already in progress. Try again in a moment.');saving=true;try{const response=await fetch('/api/collection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(next)});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not save the collection.');records=next;renderFilters();render()}finally{saving=false}}
function reset(){selectedTypes.clear();selectedColors.clear();$('search').value='';$('era').value='all';$('size').value='all';renderFilters();render()}
function openEditor(id=null){editingId=id;const record=records.find(r=>r.id===id);$('jerseyForm').reset();$('formError').textContent='';$('photo').value='';draftPhoto=record?.photo||'';$('editorTitle').textContent=id?'Edit jersey':'Add a jersey';$('save').textContent=id?'Save changes':'Save jersey';if(record){for(const key of ['name','team','number','type','color','year','size','condition','notes'])$('jerseyForm').elements[key].value=record[key]??''}else $('jerseyForm').elements.year.value=new Date().getFullYear();updatePhotoPreview();$('editor').showModal()}
function updatePhotoPreview(){$('photoPreview').hidden=!draftPhoto;$('uploadText').hidden=!!draftPhoto;$('photoPreview').src=draftPhoto||''}
function showDetail(id){const r=records.find(r=>r.id===id);if(!r)return;const age=new Date().getFullYear()-r.year;$('detailContent').innerHTML=`<div class="dialog-header"><div><span class="eyebrow">${esc(r.type)} · ${esc(r.team)}</span><h2>${esc(r.name)}</h2></div><button class="close" aria-label="Close jersey details" id="closeDetail">×</button></div>${photoMarkup(r,'detail-photo')}${r.sample?'<p class="detail-sample">Example jersey · fictional team and illustrative photo.</p>':''}<dl class="detail-facts">${[['Year',r.year],['Age',age>=0?`${age} years`:'Future season'],['Size',r.size],['Color',r.color],['Condition',r.condition],['Player / number',r.number||'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="detail-story">${esc(r.notes||'Every jersey has a story. Add yours by editing this piece.')}</p><div class="dialog-footer"><button class="text-button danger" id="deleteJersey">Remove jersey</button><button class="primary" id="editJersey">Edit jersey</button></div>`;$('closeDetail').onclick=()=>$('detail').close();$('editJersey').onclick=()=>{$('detail').close();openEditor(id)};$('deleteJersey').onclick=async()=>{if(!confirm(`Remove “${r.name}” from your collection?`))return;try{await persist(records.filter(item=>item.id!==id));$('detail').close();notify('Jersey removed from the collection.')}catch(e){notify(e.message)}};$('detail').showModal()}
$('add').onclick=()=>openEditor();$('reset').onclick=reset;$('emptyAction').onclick=()=>records.length?reset():openEditor();$('search').oninput=render;$('era').onchange=render;$('size').onchange=render;$('sort').onchange=render;
$('gridView').onclick=()=>{view='grid';setView()};$('listView').onclick=()=>{view='list';setView()};function setView(){for(const v of ['grid','list']){$(v+'View').classList.toggle('selected',view===v);$(v+'View').setAttribute('aria-pressed',String(view===v))}render()}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('detail').open&&!$('editor').open){e.preventDefault();$('search').focus()}});
$('photo').onchange=async()=>{const file=$('photo').files[0];if(!file)return;if(file.size>8*1024*1024){$('formError').textContent='Please choose a photo smaller than 8 MB.';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){$('formError').textContent='Please choose a JPG, PNG or WebP image.';return}try{const image=await createImageBitmap(file),scale=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#f8f8f2';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);draftPhoto=canvas.toDataURL('image/jpeg',.85);image.close();$('formError').textContent='';updatePhotoPreview()}catch{$('formError').textContent='This image could not be opened. Please choose another photo.'}};
$('jerseyForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const existing=records.find(r=>r.id===editingId);const record={...existing,...data,id:editingId||crypto.randomUUID(),year:Number(data.year),photo:draftPhoto,sample:false};delete record.tile;const next=editingId?records.map(r=>r.id===editingId?record:r):[record,...records];$('save').disabled=true;$('formError').textContent='';try{await persist(next);$('editor').close();notify(editingId?'Jersey details updated.':'A new chapter added to your collection.')}catch(error){$('formError').textContent=error.message}finally{$('save').disabled=false}};
$('clearSamples').onclick=async()=>{if(!confirm('Clear the example jerseys? Your own jerseys will stay in the collection.'))return;try{await persist(records.filter(r=>!r.sample));notify('Ready for your own collection.')}catch(e){notify(e.message)}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(records,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldwork-collection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Collection exported, including your photos.')};
(async()=>{try{const response=await fetch('/api/collection');if(!response.ok)throw Error('Could not load your collection. Refresh to try again.');records=await response.json();renderFilters();render()}catch(e){$('resultCount').textContent='Collection unavailable';$('cards').innerHTML=`<div class="empty"><h3>Couldn’t open the archive.</h3><p>${esc(e.message)}</p><button class="secondary" onclick="location.reload()">Try again</button></div>`}})();
